from math import sqrt, lgamma, exp, pi
# two-tailed p for Student t via numeric integration of the pdf
def pdf(x,d): return exp(lgamma((d+1)/2)-lgamma(d/2))/sqrt(d*pi)*(1+x*x/d)**(-(d+1)/2)
def p2(tv,d,N=200000,U=60.0):
    h=(U-tv)/N; s=sum(pdf(tv+(i+0.5)*h,d) for i in range(N))*h; return 2*s
for n in (18,19,20,21,22):
    print(n,[round(p2(r*sqrt(n-2)/sqrt(1-r*r),n-2),4) for r in (0.53,0.59)])
"

